local BeginnerAssembleAchievementCell = Class("BeginnerAssembleAchievementCell")

function BeginnerAssembleAchievementCell:__init()
	self.btnActionJump = nil
	self.btnActionGet  = nil
end

function BeginnerAssembleAchievementCell:__delete()
	self.btnActionJump = nil
	self.btnActionGet  = nil
	self.controller    = nil
end

---SetBtnCallBackJump
---设置单击回调函数(跳转)
function BeginnerAssembleAchievementCell:SetBtnCallBackJump(cb)
	self.btnActionJump = cb
end

---SetBtnCallBackGet
---设置单击回调函数(领取)
function BeginnerAssembleAchievementCell:SetBtnCallBackGet(cb)
	self.btnActionGet = cb
end

function BeginnerAssembleAchievementCell:GetCellDt()
	return checkTable(self.cellDt)
end

function BeginnerAssembleAchievementCell:IsHasDrawn()
	return checkInt(self:GetCellDt().hasDrawn) == 1
end

function BeginnerAssembleAchievementCell:IsCanJump()
	return checkInt(self.taskVo.openType) ~= 0
end

function BeginnerAssembleAchievementCell:IsCanDrawn()
	return (checkNumber(self:GetCellDt().progress) >= checkNumber(self.taskVo.taskContenNum)) and not self:IsHasDrawn()
end

function BeginnerAssembleAchievementCell:Awake()
	SetButtonAction(self.FontStyleButton, function()
		if self:IsCanDrawn() then
			if type(self.btnActionGet) == 'function' then
				if self:IsCanDrawn() then
					self.btnActionGet(self.cellDt)
				else
					GameUtils.Toast(localize('当前不可领取'))
				end
			end
		elseif self:IsCanJump() then
			if type(self.btnActionJump) == 'function' then
				self.btnActionJump(self.cellDt)
			end
		end
	end)
end

function BeginnerAssembleAchievementCell:FreshBaseUI(data)
	self.cellDt = checkTable(data)
	self.taskVo = CfUtils.GetCfVo(AutoIds.IdSetting8936,"BeginnerAchievementTaskVo",self.cellDt.id)
	local isHasDrawn = self:IsHasDrawn()
	local isCanDrawn = self:IsCanDrawn()
	local isCanJump  = self:IsCanJump()
	CfUtils.FillText(self.TextDescribe, self.taskVo.desc)
	CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, parse_rewards(self.taskVo.rewardId, self.taskVo.rewardNum))
	
	self.ProgressBar.value = data.progress / self.taskVo.taskContenNum
	
	CfUtils.FillText(self.TextProgress, string.format("%s/%s", data.progress, self.taskVo.taskContenNum))
	
	KTool.SetActive(self.FontStyleButton, (isCanJump and not isHasDrawn) or isCanDrawn)
	KTool.SetActive(self.TextUnderway, not isCanJump and not isHasDrawn and not isCanDrawn)
	KTool.SetActive(self.TextComplete, isHasDrawn)
	KTool.SetActive(self.CanGet, isCanDrawn)
	
	if not isHasDrawn then
		if isCanDrawn then
			self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
		elseif isCanJump then
			self.FontStyleButton:ResetFontStyle("B13", localize("前往"))
		end
	end
end

function BeginnerAssembleAchievementCell:OnDestroy()
	self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end

return BeginnerAssembleAchievementCell